<script setup>
import {computed} from 'vue';
import {bindingContract,bindingLimits,dataDescriptor,literalSchema,defaultDataValue} from '@lvgl-cbor/screen-codec';
import {expressionMode,createExpression,changeOperator,operatorArgumentSchema,hasObjectField,toggleObjectField} from './binding-model.js';
import SourcePathInput from './SourcePathInput.vue';
import DataValueInput from './DataValueInput.vue';
import Icon from '../../components/Icon.vue';
const props=defineProps({modelValue:{required:true},schema:[String,Object],capabilities:Object,eventContext:Boolean,eventSchema:[String,Object],depth:{type:Number,default:1},label:{type:String,default:'Выражение'}}),emit=defineEmits(['update:modelValue']);
const limits=computed(()=>bindingLimits(props.capabilities));
const mode=computed(()=>expressionMode(props.modelValue)),spec=computed(()=>dataDescriptor(props.schema)),literalType=computed(()=>dataDescriptor(props.schema??literalSchema(props.modelValue?.literal??'')).type);
const objectFields=computed(()=>({...spec.value?.fields,...Object.fromEntries(Object.keys(props.modelValue?.object??{}).map(key=>[key,spec.value?.fields?.[key]]))}));
const names={eq:'=',ne:'≠',lt:'<',le:'≤',gt:'>',ge:'≥',and:'И',or:'ИЛИ',not:'НЕ',select:'Если / то / иначе',add:'+',sub:'−',mul:'×',div:'÷',round:'Округлить'};
function change(mode){emit('update:modelValue',createExpression(mode,props.schema,{sources:props.capabilities?.binding?.sources,eventSchema:props.eventSchema}));}
function arg(index,value){const args=[...props.modelValue.args];args[index]=value;emit('update:modelValue',{op:props.modelValue.op,args});}
function item(index,value){const next=[...props.modelValue];next[index]=value;emit('update:modelValue',next);}
function field(key,enabled){emit('update:modelValue',{object:toggleObjectField(props.modelValue.object,key,enabled,()=>createExpression('literal',objectFields.value[key]))});}
function childSchema(index){return spec.value?.type==='tuple'?spec.value.items[index]:spec.value?.items;}
</script>
<template><div class="binding-expression" :class="{'binding-expression-nested':depth>1}">
 <div class="binding-expression-head"><select :aria-label="label+' вид'" :value="mode" @change="change($event.target.value)"><option value="source">Данные</option><option value="literal">Значение</option><option v-if="depth<limits.expressionDepth||mode==='op'" value="op">Операция</option><option v-if="eventContext&&(eventSchema!==null||mode==='event')" value="event" :disabled="eventSchema===null">Значение события{{eventSchema===null?' · недоступно':''}}</option><option v-if="spec?.type==='array'||spec?.type==='tuple'||mode==='array'" value="array">Массив выражений</option><option v-if="spec?.type==='object'||mode==='object'" value="object">Поля выражений</option></select>
 <SourcePathInput v-if="mode==='source'" :model-value="modelValue" :capabilities="capabilities" :label="label+' источник'" @update:model-value="emit('update:modelValue',$event)"/>
 <template v-else-if="mode==='literal'"><select v-if="!schema" :aria-label="label+' тип значения'" :value="literalType" @change="emit('update:modelValue',{literal:defaultDataValue({type:$event.target.value,...$event.target.value==='array'?{items:'text',maxItems:limits.arrayItems}:$event.target.value==='object'?{fields:{}}:{}})})"><option value="text">Текст</option><option value="integer">Целое</option><option value="number">Число</option><option value="bool">Флаг</option><option value="null">null</option></select><DataValueInput :capabilities="capabilities" :schema="schema" :model-value="modelValue.literal" :label="label+' значение'" @update:model-value="emit('update:modelValue',{literal:$event})"/></template>
 <select v-else-if="mode==='op'" :aria-label="label+' операция'" :value="modelValue.op" @change="emit('update:modelValue',changeOperator($event.target.value,modelValue,schema))"><option v-for="(_,name) in bindingContract.operators" :key="name" :value="name">{{names[name]??name}}</option></select><code v-else-if="mode==='event'">event.value</code>
 </div>
 <div v-if="mode==='op'" class="binding-expression-children"><div v-for="(value,index) in modelValue.args" :key="index" class="binding-expression-argument"><span class="binding-argument-name">{{modelValue.op==='select'?['Если','То','Иначе'][index]:index+1}}</span><ExpressionInput :model-value="value" :schema="operatorArgumentSchema(modelValue.op,index,schema)" :capabilities="capabilities" :event-context="eventContext" :event-schema="eventSchema" :depth="depth+1" :label="label+' / '+(index+1)" @update:model-value="arg(index,$event)"/></div></div>
 <div v-else-if="mode==='array'" class="binding-expression-children"><div v-for="(value,index) in modelValue" :key="index" class="binding-expression-argument"><span class="binding-argument-name">{{spec?.type==='tuple'?(dataDescriptor(spec.items[index]).title??index+1):index+1}}</span><ExpressionInput :model-value="value" :schema="childSchema(index)" :capabilities="capabilities" :event-context="eventContext" :event-schema="eventSchema" :depth="depth+1" :label="label+' / '+(index+1)" @update:model-value="item(index,$event)"/><button v-if="spec?.type!=='tuple'" class="action-button icon-action" :disabled="modelValue.length<=(spec?.minItems??0)" :aria-label="label+' удалить выражение '+(index+1)" data-tooltip="Удалить элемент" @click="emit('update:modelValue',modelValue.filter((_,i)=>i!==index))"><Icon name="trash"/></button></div><button v-if="spec?.type!=='tuple'" class="action-button icon-action" :disabled="modelValue.length>=(spec?.maxItems??limits.arrayItems)" :aria-label="label+' добавить выражение'" data-tooltip="Добавить выражение в массив" @click="emit('update:modelValue',[...modelValue,createExpression('literal',spec?.items)])"><Icon name="plus"/></button></div>
 <div v-else-if="mode==='object'" class="binding-expression-children"><div v-for="(fieldSchema,key) in objectFields" :key="key" class="binding-expression-argument"><label class="binding-field-label"><input type="checkbox" :aria-label="label+' / '+key+' задано'" :checked="hasObjectField(modelValue.object,key)" @change="field(key,$event.target.checked)"><span :title="key">{{dataDescriptor(fieldSchema)?.title??key}}</span></label><ExpressionInput v-if="hasObjectField(modelValue.object,key)" :model-value="modelValue.object[key]" :schema="fieldSchema" :capabilities="capabilities" :event-context="eventContext" :event-schema="eventSchema" :depth="depth+1" :label="label+' / '+key" @update:model-value="emit('update:modelValue',{object:{...modelValue.object,[key]:$event}})"/><span v-else class="binding-field-absent">Не задано</span></div></div>
</div></template>
